function renderWithCitations(text, onCitationClick) {
  const source = String(text);
  const citationPattern = /\[(\d+)\]/;
  const parts = [];
  const linkedRuleKeysInText = new Set();
  let cursor = 0;
  let safety = 0;

  while (cursor < source.length && safety < 100) {
    safety += 1;
    const remaining = source.slice(cursor);
    const candidates = [];
    const citationMatch = remaining.match(citationPattern);

    if (citationMatch) {
      candidates.push({
        index: citationMatch.index,
        text: citationMatch[0],
        citationId: citationMatch[1],
        type: "citation",
      });
    }

    articleLinkRules.forEach((rule) => {
      const ruleKey = getArticleLinkRuleKey(rule);

      if (linkedRuleKeysInText.has(ruleKey)) {
        return;
      }

      const keywordMatch = remaining.match(rule.pattern);

      if (keywordMatch) {
        candidates.push({
          index: keywordMatch.index,
          text: keywordMatch[0],
          rule,
          ruleKey,
          type: "keyword",
        });
      }
    });

    if (!candidates.length) {
      parts.push(remaining);
      break;
    }

    candidates.sort((a, b) => a.index - b.index || b.text.length - a.text.length);
    const next = candidates[0];
    const absoluteIndex = cursor + next.index;

    if (absoluteIndex > cursor) {
      parts.push(source.slice(cursor, absoluteIndex));
    }

    if (next.type === "citation") {
      parts.push(
        <button
          key={`${next.text}-${absoluteIndex}`}
          type="button"
          onClick={() => onCitationClick(next.citationId)}
          className="mx-0.5 inline cursor-pointer rounded px-0.5 font-black text-[#7835A4] underline decoration-[#7835A4]/40 underline-offset-2 transition hover:bg-[#f4ecf8] hover:text-[#4c1d6b]"
          title={"View resource " + next.citationId}
        >
          {next.text}
        </button>
      );
    } else {
      linkedRuleKeysInText.add(next.ruleKey);
      parts.push(
        <a
          key={`${next.text}-${absoluteIndex}`}
          href={next.rule.href}
          className="font-black text-[#7835A4] underline decoration-[#7835A4]/35 underline-offset-2 transition hover:bg-[#f4ecf8] hover:text-[#4c1d6b]"
        >
          {next.text}
        </a>
      );
    }

    cursor = absoluteIndex + next.text.length;
  }

  return parts.map((part, index) =>
    typeof part === "string" ? <React.Fragment key={`${part}-${index}`}>{part}</React.Fragment> : part
  );
}

function renderPastedLine(line, index, onCitationClick) {
  const trimmed = line.trim();

  if (!trimmed) return <div key={index} className="h-3" />;

  if (index === 0 && /^URL\s*:/i.test(trimmed)) {
    return <a key={index} href={trimmed.replace(/^URL\s*:\s*/, "")} className="break-words text-[13px] font-bold text-[#7835A4] underline underline-offset-4">{trimmed}</a>;
  }

  if (trimmed === "Teen Stress & Anxiety Treatment in India") {
    return <h2 key={index} className="mt-8 text-[28px] font-black leading-tight text-[#292064] sm:text-[36px]">{trimmed}</h2>;
  }

  if (pastedSectionHeadings.has(trimmed)) {
    return <h2 key={index} className="mt-8 text-[22px] font-black leading-tight text-[#17111f]">{trimmed}</h2>;
  }

  if (pastedSubHeadings.has(trimmed) || pastedFaqQuestions.has(trimmed)) {
    return <h3 key={index} className="mt-5 text-[17px] font-black leading-snug text-[#21142d]">{trimmed}</h3>;
  }

  if (trimmed.startsWith("*") || trimmed.startsWith("-") || trimmed.startsWith("?") || trimmed.startsWith("?")) {
    return <p key={index} className="mt-2 pl-4 text-[14px] font-semibold leading-7 text-[#51465a]">{renderWithCitations(trimmed, onCitationClick)}</p>;
  }

  if (trimmed === "Book a Consultation Today" || trimmed === "Schedule a consultation today!") {
    return <p key={index} className="mt-5 text-[17px] font-black text-[#7835A4]">{trimmed}</p>;
  }

  return <p key={index} className="mt-3 text-[14px] font-semibold leading-7 text-[#51465a]">{renderWithCitations(line, onCitationClick)}</p>;
}

